using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Look for all items in the Services project
var projects = build.FindChildrenRecursive<Project>().Where(p => p.Name == "Services.csproj");
foreach (var proj in projects.Take(3))
{
    Console.WriteLine($"Project instance: {proj.Name}");
    var addItems = proj.FindChildrenRecursive<AddItem>();
    foreach (var ai in addItems.Where(a => a.Name == "PackageReference" || a.Name == "ProjectReference"))
    {
        Console.WriteLine($"  {ai.Name}:");
        foreach (var child in ai.Children)
        {
            Console.WriteLine($"    {child}");
        }
    }
    Console.WriteLine("---");
}

// Also look at the source files referenced
Console.WriteLine("\n=== Source files compiled in Services ===");
foreach (var proj in projects.Take(1))
{
    var compileItems = proj.FindChildrenRecursive<AddItem>().Where(a => a.Name == "Compile");
    foreach (var ci in compileItems)
    {
        foreach (var child in ci.Children)
        {
            Console.WriteLine($"  {child}");
        }
    }
}
EOF
